using UniToStudyHub.Models;
namespace UniToStudyHub.Services;
public sealed class DocumentSyncService
{
 public async Task<int> DownloadCourseFilesAsync(MoodleClient client,Course course,IEnumerable<MoodleCourseSection> sections,CancellationToken cancellationToken=default){var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"UniToStudyHub",SafeName(course.Name));var count=0;foreach(var file in sections.Where(s=>s.modules is not null).SelectMany(s=>s.modules).Where(m=>m.contents is not null).SelectMany(m=>m.contents).Where(f=>f.type.Equals("file",StringComparison.OrdinalIgnoreCase)&&!string.IsNullOrWhiteSpace(f.fileurl)&&!string.IsNullOrWhiteSpace(f.filename))){cancellationToken.ThrowIfCancellationRequested();var dest=Path.Combine(root,Categorize(file.filename,file.mimetype),SafeName(file.filename));if(File.Exists(dest))continue;try{await client.DownloadFileAsync(file.fileurl,dest,cancellationToken);count++;}catch(Exception ex) when(ex is HttpRequestException or InvalidOperationException or IOException){if(File.Exists(dest))File.Delete(dest);}}return count;}
 public static string Categorize(string name,string mime){var ext=Path.GetExtension(name).ToLowerInvariant();if(name.Contains("syllabus",StringComparison.OrdinalIgnoreCase)||name.Contains("programma",StringComparison.OrdinalIgnoreCase))return "Syllabus";if(ext==".pdf"||mime.Contains("pdf",StringComparison.OrdinalIgnoreCase))return "PDF";if(ext is ".ppt" or ".pptx" or ".odp"||mime.Contains("presentation",StringComparison.OrdinalIgnoreCase))return "Slide";if(ext is ".csv" or ".xls" or ".xlsx" or ".json" or ".zip" or ".parquet" or ".sav" or ".dta")return "Dataset";return "Altro";}
 private static string SafeName(string value){var invalid=Path.GetInvalidFileNameChars();var s=new string(value.Select(c=>invalid.Contains(c)||c=='/'||c=='\\'?'_':c).ToArray()).Trim().TrimEnd('.');if(string.IsNullOrWhiteSpace(s)||s is "." or "..")s="Senza-nome";if(s.Length>120)s=s[..120];var stem=Path.GetFileNameWithoutExtension(s);if(new[]{"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"}.Contains(stem,StringComparer.OrdinalIgnoreCase))s="_"+s;return s;}
}